import { Alert, Box, Button, Divider, Stack, TextField, Typography } from '@mui/material'
import Add from 'mdi-material-ui/Plus'
import DeleteOutline from 'mdi-material-ui/DeleteOutline'
import Pencil from 'mdi-material-ui/Pencil'
import type { ChangeEvent } from 'react'
import { useEffect, useMemo, useState } from 'react'
import { BUILTIN_AGENT_PROFILES, MODEL_PLACEHOLDER, SESSION_ID_PLACEHOLDER, type AgentProfile } from '../../data/agent_profiles'

const COMMA_SEPARATOR = ','

interface AgentProfilesEditorProps {
    disabled?: boolean
    onChange: (value: AgentProfile[]) => void
    onValidityChange?: (valid: boolean) => void
    value: AgentProfile[]
}

interface AgentProfileRowProps {
    disabled: boolean
    removable: boolean
    profile: AgentProfile
    onEdit: (name: string) => void
    onRemove: (name: string) => void
}

interface AgentProfileFormProps {
    disabled: boolean
    errors: string[]
    form: AgentProfileFormState
    onCancel: () => void
    onSave: () => void
    onTextChange: (event: ChangeEvent<HTMLInputElement>) => void
}

interface AgentProfileFormState {
    accessLevelArgument: string
    accessLevels: string
    approvalPolicies: string
    approvalPolicyArgument: string
    command: string
    defaultAccessLevel: string
    defaultApprovalPolicy: string
    defaultModel: string
    modelArgument: string
    models: string
    name: string
    resumeCommand: string
}

function toFormState(profile?: AgentProfile): AgentProfileFormState {
    return {
        accessLevelArgument: profile?.accessLevelArgument ?? '',
        accessLevels: profile?.accessLevels?.join(`${COMMA_SEPARATOR} `) ?? '',
        approvalPolicies: profile?.approvalPolicies?.join(`${COMMA_SEPARATOR} `) ?? '',
        approvalPolicyArgument: profile?.approvalPolicyArgument ?? '',
        command: profile ? JSON.stringify(profile.command) : '',
        defaultAccessLevel: profile?.defaultAccessLevel ?? '',
        defaultApprovalPolicy: profile?.defaultApprovalPolicy ?? '',
        defaultModel: profile?.defaultModel ?? '',
        modelArgument: profile?.modelArgument ?? '',
        models: profile?.models?.join(`${COMMA_SEPARATOR} `) ?? '',
        name: profile?.name ?? '',
        resumeCommand: profile?.resumeCommand ? JSON.stringify(profile.resumeCommand) : '',
    }
}

function readModels(value: string) {
    return value.split(COMMA_SEPARATOR).map((model) => model.trim()).filter((model) => model.length > 0)
}

function readCommand(value: string) {
    const command: unknown = JSON.parse(value)
    if (!Array.isArray(command) || command.length === 0 || command.some((argument) => typeof argument !== 'string' || argument.length === 0)) {
        throw new Error('Command must be a non-empty JSON array of strings.')
    }

    return command
}

function toAgentProfile(form: AgentProfileFormState): AgentProfile {
    const models = readModels(form.models)
    const accessLevels = readModels(form.accessLevels)
    const approvalPolicies = readModels(form.approvalPolicies)

    return {
        ...(accessLevels.length > 0 ? {
            accessLevelArgument: form.accessLevelArgument.trim(),
            accessLevels,
            defaultAccessLevel: form.defaultAccessLevel.trim(),
        } : {}),
        ...(approvalPolicies.length > 0 ? {
            approvalPolicies,
            approvalPolicyArgument: form.approvalPolicyArgument.trim(),
            defaultApprovalPolicy: form.defaultApprovalPolicy.trim(),
        } : {}),
        command: readCommand(form.command),
        ...(form.defaultModel.trim().length > 0 ? { defaultModel: form.defaultModel.trim() } : {}),
        ...(form.modelArgument.trim().length > 0 ? { modelArgument: form.modelArgument.trim() } : {}),
        models,
        name: form.name.trim(),
        ...(form.resumeCommand.trim().length > 0 ? { resumeCommand: readCommand(form.resumeCommand) } : {}),
    }
}

function validateForm(form: AgentProfileFormState, usedNames: string[]) {
    const errors: string[] = []
    const name = form.name.trim()
    const command = form.command.trim()
    const models = readModels(form.models)
    const defaultModel = form.defaultModel.trim()
    const accessLevels = readModels(form.accessLevels)
    const approvalPolicies = readModels(form.approvalPolicies)

    if (name.length === 0) errors.push('Name is required.')
    if (usedNames.includes(name)) errors.push(`Duplicate agent profile: ${name}`)
    if (command.length === 0) errors.push('Command is required.')
    else {
        try {
            readCommand(command)
        } catch (error) {
            errors.push(error instanceof Error ? error.message : 'Invalid command.')
        }
    }
    if (form.resumeCommand.trim().length > 0) {
        try {
            readCommand(form.resumeCommand)
        } catch (error) {
            errors.push(error instanceof Error ? `Resume ${error.message.toLowerCase()}` : 'Invalid resume command.')
        }
    }
    if (models.length === 0) errors.push('At least one model is required.')
    if (new Set(models).size !== models.length) errors.push('Model names must be unique.')
    if (defaultModel.length > 0 && models.length > 0 && !models.includes(defaultModel)) {
        errors.push(`Default model must be one of: ${models.join(', ')}`)
    }
    if (accessLevels.length > 0 && form.accessLevelArgument.trim().length === 0) errors.push('Access-level argument is required.')
    if (new Set(accessLevels).size !== accessLevels.length) errors.push('Access levels must be unique.')
    if (accessLevels.length > 0 && !accessLevels.includes(form.defaultAccessLevel.trim())) errors.push('Default access level must match a configured choice.')
    if (accessLevels.length === 0 && (form.accessLevelArgument.trim().length > 0 || form.defaultAccessLevel.trim().length > 0)) {
        errors.push('Access-level choices are required when argument or default is set.')
    }
    if (approvalPolicies.length > 0 && form.approvalPolicyArgument.trim().length === 0) errors.push('Approval-policy argument is required.')
    if (new Set(approvalPolicies).size !== approvalPolicies.length) errors.push('Approval policies must be unique.')
    if (approvalPolicies.length > 0 && !approvalPolicies.includes(form.defaultApprovalPolicy.trim())) errors.push('Default approval policy must match a configured choice.')
    if (approvalPolicies.length === 0 && (form.approvalPolicyArgument.trim().length > 0 || form.defaultApprovalPolicy.trim().length > 0)) {
        errors.push('Approval-policy choices are required when argument or default is set.')
    }

    return errors
}

function isBuiltinName(name: string) {
    return BUILTIN_AGENT_PROFILES.some((profile) => profile.name === name)
}

function AgentProfileRow(props: AgentProfileRowProps) {
    const { disabled, onEdit, onRemove, profile, removable } = props

    const editProfile = () => {
        onEdit(profile.name)
    }

    const removeProfile = () => {
        onRemove(profile.name)
    }

    return (
        <Box sx={{ border: 1, borderColor: 'divider', borderRadius: 1, p: 1.5 }}>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} sx={{ alignItems: { sm: 'center' } }}>
                <Box sx={{ flex: 1, minWidth: 0 }}>
                    <Typography sx={{ fontWeight: 700 }}>{profile.name}</Typography>
                    <Typography color="text.secondary" sx={{ overflowWrap: 'anywhere' }} variant="body2">
                        {JSON.stringify(profile.command)}
                    </Typography>
                </Box>
                <Stack direction="row" spacing={1}>
                    <Button aria-label={`Edit ${profile.name}`} disabled={disabled} onClick={editProfile} size="small" startIcon={<Pencil />} variant="outlined">
                        Edit
                    </Button>
                    {removable ? (
                        <Button aria-label={`Remove ${profile.name}`} color="error" disabled={disabled} onClick={removeProfile} size="small" startIcon={<DeleteOutline />} variant="outlined">
                            Remove
                        </Button>
                    ) : <Typography color="text.secondary" variant="body2">Built-in</Typography>}
                </Stack>
            </Stack>
        </Box>
    )
}

function AgentProfileForm(props: AgentProfileFormProps) {
    const { disabled, errors, form, onCancel, onSave, onTextChange } = props
    const canSave = !disabled && errors.length === 0

    return (
        <Box sx={{ border: 1, borderColor: 'divider', borderRadius: 1, p: 2 }}>
            <Stack spacing={2}>
                {errors.length > 0 ? <Alert severity="error">{errors.join(' ')}</Alert> : null}
                <TextField disabled={disabled} fullWidth label="Name" name="name" onChange={onTextChange} size="small" value={form.name} />
                <TextField
                    disabled={disabled}
                    fullWidth
                    helperText={`JSON string array. May include ${MODEL_PLACEHOLDER}.`}
                    label="Command"
                    name="command"
                    onChange={onTextChange}
                    size="small"
                    value={form.command}
                />
                <TextField disabled={disabled} fullWidth label="Model argument" name="modelArgument" onChange={onTextChange} size="small" value={form.modelArgument} />
                <TextField disabled={disabled} fullWidth helperText="Comma-separated model names." label="Models" name="models" onChange={onTextChange} size="small" value={form.models} />
                <TextField disabled={disabled} fullWidth label="Profile default model" name="defaultModel" onChange={onTextChange} size="small" value={form.defaultModel} />
                <TextField disabled={disabled} fullWidth helperText="Comma-separated provider values. Leave empty when unsupported." label="Access levels" name="accessLevels" onChange={onTextChange} size="small" value={form.accessLevels} />
                <TextField disabled={disabled} fullWidth label="Access-level argument" name="accessLevelArgument" onChange={onTextChange} size="small" value={form.accessLevelArgument} />
                <TextField disabled={disabled} fullWidth label="Default access level" name="defaultAccessLevel" onChange={onTextChange} size="small" value={form.defaultAccessLevel} />
                <TextField disabled={disabled} fullWidth helperText="Comma-separated provider values. Leave empty when unsupported." label="Approval policies" name="approvalPolicies" onChange={onTextChange} size="small" value={form.approvalPolicies} />
                <TextField disabled={disabled} fullWidth label="Approval-policy argument" name="approvalPolicyArgument" onChange={onTextChange} size="small" value={form.approvalPolicyArgument} />
                <TextField disabled={disabled} fullWidth label="Default approval policy" name="defaultApprovalPolicy" onChange={onTextChange} size="small" value={form.defaultApprovalPolicy} />
                <TextField
                    disabled={disabled}
                    fullWidth
                    helperText={`JSON string array. May include ${SESSION_ID_PLACEHOLDER}.`}
                    label="Resume command"
                    name="resumeCommand"
                    onChange={onTextChange}
                    size="small"
                    value={form.resumeCommand}
                />
                <Stack direction="row" spacing={1}>
                    <Button disabled={!canSave} onClick={onSave} variant="contained">
                        Save profile
                    </Button>
                    <Button disabled={disabled} onClick={onCancel} variant="outlined">
                        Cancel
                    </Button>
                </Stack>
            </Stack>
        </Box>
    )
}

export function AgentProfilesEditor(props: AgentProfilesEditorProps) {
    const { disabled = false, onChange, onValidityChange, value } = props
    const [editingName, setEditingName] = useState<string | null>(null)
    const [form, setForm] = useState<AgentProfileFormState | null>(null)
    const storedBuiltinProfiles = value.filter((profile) => isBuiltinName(profile.name))
    const userProfiles = value.filter((profile) => !isBuiltinName(profile.name))
    const builtinProfiles = BUILTIN_AGENT_PROFILES.map((profile) => (
        storedBuiltinProfiles.find((storedProfile) => storedProfile.name === profile.name) ?? profile
    ))
    const usedNames = useMemo(
        () => [...BUILTIN_AGENT_PROFILES, ...userProfiles]
            .map((profile) => profile.name)
            .filter((name) => name !== editingName),
        [editingName, userProfiles],
    )
    const errors = form ? validateForm(form, usedNames) : []

    useEffect(() => {
        onValidityChange?.(errors.length === 0)
    }, [errors.length, onValidityChange])

    const startAdd = () => {
        setEditingName(null)
        setForm(toFormState())
    }

    const editProfile = (name: string) => {
        const profile = [...builtinProfiles, ...userProfiles].find((item) => item.name === name)
        if (!profile) return

        setEditingName(name)
        setForm(toFormState(profile))
    }

    const removeProfile = (name: string) => {
        onChange([...storedBuiltinProfiles, ...userProfiles.filter((profile) => profile.name !== name)])
    }

    const cancelEdit = () => {
        setEditingName(null)
        setForm(null)
    }

    const saveProfile = () => {
        if (!form || errors.length > 0) return

        const nextProfile = toAgentProfile(form)
        const retainedProfiles = value.filter((profile) => profile.name !== editingName)
        onChange([...retainedProfiles, nextProfile])
        cancelEdit()
    }

    const handleTextChange = (event: ChangeEvent<HTMLInputElement>) => {
        const field = event.target.name as keyof AgentProfileFormState
        setForm((currentForm) => (currentForm ? { ...currentForm, [field]: event.target.value } : currentForm))
    }

    return (
        <Stack spacing={2}>
            <Stack spacing={1}>
                {builtinProfiles.map((profile) => (
                    <AgentProfileRow
                        disabled={disabled}
                        key={profile.name}
                        onEdit={editProfile}
                        onRemove={removeProfile}
                        profile={profile}
                        removable={false}
                    />
                ))}
                {userProfiles.map((profile) => (
                    <AgentProfileRow
                        disabled={disabled}
                        key={profile.name}
                        onEdit={editProfile}
                        onRemove={removeProfile}
                        profile={profile}
                        removable
                    />
                ))}
            </Stack>
            <Divider />
            {form ? (
                <AgentProfileForm
                    disabled={disabled}
                    errors={errors}
                    form={form}
                    onCancel={cancelEdit}
                    onSave={saveProfile}
                    onTextChange={handleTextChange}
                />
            ) : (
                <Button disabled={disabled} onClick={startAdd} startIcon={<Add />} variant="outlined">
                    Add profile
                </Button>
            )}
        </Stack>
    )
}

