        render(
            <AppThemeProvider>
                <ActionAgentSelectors
                    accessLevel=""
                    agent="custom"
                    agentAvailability={{ custom: { available: true, error: null } }}
                    agentProfiles={[{ command: ['custom'], models: ['model'], name: 'custom' }]}
                    approvalPolicy=""
                    disabled={false}
                    model="model"
                    selectedAccessLevels={[]}
                    selectedAgentModels={['model']}
                    selectedApprovalPolicies={[]}
